const sources = [
 { name: 'EU Funding & Tenders', url: 'https://ec.europa.eu/info/funding-tenders/opportunities/portal/screen/opportunities/rss' },
 { name: 'EU Startups News', url: 'https://www.eu-startups.com/feed/' },
 { name: 'Sifted', url: 'https://sifted.eu/feed' }
];
return sources.map(source => ({ json: { ...source } }));

const source = $('Load source registry').item.json;
const item = $json;
const title = String(item.title || '').trim();
const url = String(item.link || item.guid || '').trim();
const description = String(item.contentSnippet || item.content || item.description || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
if (!title || !url) return [];
let hash = 0; for (let i = 0; i < url.length; i++) hash = ((hash << 5) - hash + url.charCodeAt(i)) | 0;
return [{ json: { id: String(hash), title, url, description: description.slice(0,5000), publishedAt: item.isoDate || item.pubDate || null, source: source.name, discoveredAt: new Date().toISOString() } }];

const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};
const cutoff = Date.now() - 30*24*60*60*1000;
for (const [key, ts] of Object.entries(state.seen)) if (ts < cutoff) delete state.seen[key];
const key = $json.url.toLowerCase().replace(/\/$/, '');
if (state.seen[key]) return [];
state.seen[key] = Date.now();
return [{ json: $json }];

const original = $('Deduplicate (30-day window)').item.json;
const raw = $json.choices?.[0]?.message?.content;
if (!raw) throw new Error('AI response missing choices[0].message.content');
let a; try { a = JSON.parse(raw); } catch (e) { throw new Error('AI returned invalid JSON: ' + e.message); }
const clamp = n => Math.max(0, Math.min(100, Number(n) || 0));
const relevance = clamp(a.relevance), eligibility = clamp(a.eligibility), credibility = clamp(a.credibility);
const score = Math.round(relevance*.5 + eligibility*.3 + credibility*.2);
return [{ json: { ...original, ...a, relevance, eligibility, credibility, score, priority: score >= 80 ? 'high' : score >= 60 ? 'medium' : 'low', analyzedAt: new Date().toISOString(), schemaVersion: '1.0' } }];

const state = $getWorkflowStaticData('global');
state.reviewQueue = state.reviewQueue || [];
state.reviewQueue.push({ id:$json.id, title:$json.title, url:$json.url, source:$json.source, score:$json.score, category:$json.category, summary:$json.summary, deadline:$json.deadline, queuedAt:new Date().toISOString() });
state.reviewQueue = state.reviewQueue.slice(-500);
return [{ json: { queued:true, opportunityId:$json.id, score:$json.score, priority:$json.priority } }];
